import { EventEmitter } from 'eventemitter3';
import { IBroadcastMessage } from './types';

export interface Events {
    showBonusInPlay(gameName: string, showCancelButton: boolean, showBonusInPlay?: boolean): void;
    showGameInGameFreeze(): void;
    showTimeKeeper(limit: number): void;
    showIdVerification(): void;
    showLoadingSpinner(message?: string): void;
    hideLoadingSpinner(): void;
    showLowFunds(): void;
    showRealityCheck(): void;
    hideRealityCheck(): void;
    showSocialShare(title: string, url: string, image: string): void;
    showToast(title: string, message: string, duration?: number): void;
    showTopPrize(data: IBroadcastMessage): void;
    showPopup(title: string, message: string, button: string, onClosed?: () => void): void;
    showCooloffWindow(): void;
    showTimeLimitWindow(): void;
    showInvalidStake(minRequiredStake: string, minRequiredStakeAsPence: number, gameName: string): void
    nicknameSet(nickname: string): void;
    enterDemoMode(): void;
    leaveDemoMode(): void;
    outOfPlays(): void;
    showAutoWithdraw(onClosed?: () => void): void;
    closeAutoWithdraw(): void;
    showSelfExclusion(): void;
    hideSelfExclusion(): void;
    showTenMinuteWarning(data: { title: string; body: string; continueButton: string }): void;
    showImmediateLogout(data: { title: string; body: string; smallPrint: string; continueButton: string }): void;
    showSessionNotification(data: { 
        title: string; 
        body: string; 
        timeSpentLabel: string; 
        timeSpentValue: string; 
        moneySpentLabel: string; 
        moneySpentValue: string; 
        smallPrint: string; 
        continueButton: string 
    }): void;
}

export const OverlaysEventEmitter = new EventEmitter<Events>();
